    localparam [799:0] EXPECTED_LOGITS = {
        512'h0000155bfffff403fffff99bffffc932ffff8535ffffed1200001722ffffd66affffde7affffb607fffff013fffff2520000076efffff342ffffae31ffffb1cb,
        288'hffffe839fffff09c0000067cffffe592fffe9ddafffff62effff3be7000043fe0000bf2b
    };

